```typescript
import React, { useRef, useEffect, useState } from 'react';

interface ReasoningFrame {
  id: string;
  title: string;
  body: string;
  tokens: number;
}

interface ReasoningPanelProps {
  frames: ReasoningFrame[];
  isStreaming: boolean;
  onSeek?: (id: string) => void;
}

const ReasoningPanel: React.FC<ReasoningPanelProps> = ({ frames, isStreaming, onSeek }) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const isUserScrolledRef = useRef<boolean>(false);
  const [totalTokens, setTotalTokens] = useState<number>(0);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const handleScroll = () => {
      const { scrollTop, scrollHeight, clientHeight } = container;
      const threshold = 50;
      const isAtBottom = scrollHeight - scrollTop - clientHeight < threshold;
      isUserScrolledRef.current = !isAtBottom;
    };

    container.addEventListener('scroll', handleScroll);
    return () => {
      container.removeEventListener('scroll', handleScroll);
    };
  }, []);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    if (!isUserScrolledRef.current) {
      container.scrollTop = container.scrollHeight;
    }
  }, [frames.length]);

  useEffect(() => {
    const sum = frames.reduce((acc: number, frame: ReasoningFrame) => acc + frame.tokens, 0);
    setTotalTokens(sum);
  }, [frames]);

  return (
    <div
      ref={containerRef}
      style={{
        height: '400px',
        overflowY: 'auto',
        border: '1px solid #ccc',
        padding: '10px',
        fontFamily: 'monospace',
      }}
    >
      <div style={{ marginBottom: '10px', fontWeight: 'bold' }}>
        Total Tokens: {totalTokens}
      </div>
      {frames.map((frame: ReasoningFrame) => (
        <div
          key={frame.id}
          style={{
            marginBottom: '10px',
            padding: '8px',
            backgroundColor: '#f9f9f9',
            borderRadius: '4px',
            cursor: onSeek ? 'pointer' : 'default',
          }}
          onClick={() => {
            if (onSeek) {
              onSeek(frame.id);
            }
          }}
        >
          <div style={{ fontWeight: 'bold' }}>
            {frame.title} ({frame.tokens} tokens)
          </div>
          <div style={{ whiteSpace: 'pre-wrap', marginTop: '4px' }}>
            {frame.body}
          </div>
        </div>
      ))}
      {isStreaming && (
        <div style={{ fontStyle: 'italic', color: '#888' }}>
          Streaming...
        </div>
      )}
    </div>
  );
};

export default ReasoningPanel;
