```tsx
import React, { useRef, useEffect, useState, useCallback } from 'react';

interface ReasoningFrame {
  id: string;
  title: string;
  body: string;
  tokens: number;
}

interface ReasoningPanelProps {
  frames: ReasoningFrame[];
  isStreaming: boolean;
  onSeek?: (id: string) => void;
}

const ReasoningPanel: React.FC<ReasoningPanelProps> = ({ frames, isStreaming, onSeek }) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const userHasScrolledRef = useRef<boolean>(false);
  const [totalTokens, setTotalTokens] = useState<number>(0);

  // 计算总 token 数
  useEffect(() => {
    const sum = frames.reduce((acc: number, frame: ReasoningFrame) => acc + frame.tokens, 0);
    setTotalTokens(sum);
  }, [frames]);

  // 处理滚动事件，检测用户是否手动滚动
  const handleScroll = useCallback((): void => {
    const container = containerRef.current;
    if (!container) return;

    const { scrollTop, scrollHeight, clientHeight } = container;
    const isAtBottom = scrollHeight - scrollTop - clientHeight < 50;

    if (isAtBottom) {
      userHasScrolledRef.current = false;
    } else {
      userHasScrolledRef.current = true;
    }
  }, []);

  // 当 frames 长度变化时，如果用户没有手动滚动，则自动滚动到底部
  useEffect(() => {
    if (!userHasScrolledRef.current && containerRef.current) {
      const container = containerRef.current;
      container.scrollTop = container.scrollHeight;
    }
  }, [frames.length]);

  // 重置用户滚动状态当不再流式时
  useEffect(() => {
    if (!isStreaming) {
      userHasScrolledRef.current = false;
    }
  }, [isStreaming]);

  const handleFrameClick = useCallback((id: string): void => {
    if (onSeek) {
      onSeek(id);
    }
  }, [onSeek]);

  return (
    <div
      ref={containerRef}
      onScroll={handleScroll}
      style={{
        height: '400px',
        overflowY: 'auto',
        border: '1px solid #ccc',
        padding: '16px',
        fontFamily: 'system-ui, -apple-system, sans-serif',
        position: 'relative',
      }}
    >
      <div
        style={{
          position: 'sticky',
          top: 0,
          backgroundColor: '#f5f5f5',
          padding: '8px 0',
          borderBottom: '1px solid #ddd',
          marginBottom: '8px',
          fontWeight: 'bold',
        }}
      >
        总 Token 数: {totalTokens}
        {isStreaming && <span style={{ marginLeft: '8px', color: '#007bff' }}>（流式生成中...）</span>}
      </div>

      {frames.length === 0 ? (
        <div style={{ color: '#999', fontStyle: 'italic' }}>暂无推理帧</div>
      ) : (
        <div>
          {frames.map((frame: ReasoningFrame, index: number) => (
            <div
              key={frame.id}
              onClick={() => handleFrameClick(frame.id)}
              style={{
                marginBottom: '12px',
                padding: '12px',
                backgroundColor: index % 2 === 0 ? '#fafafa' : '#ffffff',
                borderRadius: '4px',
                cursor: onSeek ? 'pointer' : 'default',
                border: '1px solid #eee',
              }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
                <span style={{ fontWeight: 'bold', fontSize: '14px' }}>{frame.title}</span>
                <span style={{ fontSize: '12px', color: '#666', backgroundColor: '#e0e0e0', padding: '2px 6px', borderRadius: '4px' }}>
                  {frame.tokens} tokens
                </span>
              </div>
              <div style={{ fontSize: '13px', color: '#333', whiteSpace: 'pre-wrap', lineHeight: '1.5' }}>
                {frame.body}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default ReasoningPanel;
