interface ReasoningFrame {
  id: string;
  title: string;
  body: string;
  tokens: number;
}

interface ReasoningPanelProps {
  frames: ReasoningFrame[];
  isStreaming: boolean;
  onSeek?: (id: string) => void;
}

export function ReasoningPanel({ frames, isStreaming, onSeek }: ReasoningPanelProps): JSX.Element {
  const listRef = useRef<HTMLDivElement | null>(null);
  const isUserScrolledRef = useRef<boolean>(false);

  const totalTokens: number = frames.reduce((acc: number, f: ReasoningFrame) => acc + f.tokens, 0);

  useEffect(() => {
    if (!isStreaming) {
      return;
    }
    if (!isUserScrolledRef.current) {
      const el: HTMLDivElement | null = listRef.current;
      if (el) {
        el.scrollTop = el.scrollHeight;
      }
    }
  }, [frames.length, isStreaming]);

  const handleScroll = (): void => {
    const el: HTMLDivElement | null = listRef.current;
    if (!el) return;
    const threshold: number = 50;
    const isAtBottom: boolean = el.scrollTop + el.clientHeight >= el.scrollHeight - threshold;
    if (isAtBottom) {
      isUserScrolledRef.current = false;
    } else {
      isUserScrolledRef.current = true;
    }
  };

  const scrollToBottom = (): void => {
    const el: HTMLDivElement | null = listRef.current;
    if (el) {
      el.scrollTop = el.scrollHeight;
      isUserScrolledRef.current = false;
    }
  };

  return (
    <div style={styles.container}>
      <div
        ref={listRef}
        style={styles.list}
        onScroll={handleScroll}
      >
        {frames.map((frame: ReasoningFrame) => (
          <div key={frame.id} style={styles.frame}>
            <div style={styles.frameHeader}>
              <span style={styles.frameTitle}>{frame.title}</span>
              <span
                style={styles.frameTokens}
                onClick={() => onSeek && onSeek(frame.id)}
                title={`点击定位，${frame.tokens} tokens`}
              >
                {frame.tokens} tok
              </span>
            </div>
            <div style={styles.frameBody}>{frame.body}</div>
          </div>
        ))}
      </div>
      <div style={styles.footer}>
        <span>
          共 {frames.length} 帧 · 合计 {totalTokens} tokens
          {isStreaming ? ' · 正在流式生成' : ''}
          {isUserScrolledRef.current ? ' · 已暂停自动滚动' : ''}
        </span>
        {isUserScrolledRef.current && (
          <button
            onClick={scrollToBottom}
            style={{
              marginLeft: 8,
              fontSize: 12,
              padding: '2px 8px',
              border: '1px solid #bbb',
              borderRadius: 4,
              background: '#fff',
              cursor: 'pointer',
            }}
          >
            回到顶部? No, 回到底部
          </button>
        )}
      </div>
    </div>
  );
}
