interface ReasoningFrame { id: string; title: string; body: string; tokens: number }

interface ReasoningPanelProps { frames: ReasoningFrame[]; isStreaming: boolean; onSeek?: (id: string) => void }

const ReasoningPanel: React.FC<ReasoningPanelProps> = ({ frames, isStreaming, onSeek }) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const isUserScrolledRef = useRef<boolean>(false);
  const userScrolledTimerRef = useRef<number | null>(null);

  const handleScroll = () => {
    if (!containerRef.current) return;
    const { scrollTop, scrollHeight, clientHeight } = containerRef.current;
    const threshold = 50;
    const isAtBottom = scrollHeight - scrollTop - clientHeight < threshold;

    if (!isAtBottom) {
      isUserScrolledRef.current = true;
      if (userScrolledTimerRef.current !== null) {
        clearTimeout(userScrolledTimerRef.current);
      }
    } else {
      isUserScrolledRef.current = false;
    }
  };

  const clearUserScrolled = () => {
    isUserScrolledRef.current = false;
  };

  useEffect(() => {
    const timer = setTimeout(clearUserScrolled, 2000);
    return () => clearTimeout(timer);
  }, [frames.length]);

  useEffect(() => {
    if (containerRef.current && !isUserScrolledRef.current && isStreaming) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [frames.length, isStreaming]);

  const totalTokens: number = frames.reduce((acc: number, frame: ReasoningFrame) => acc + frame.tokens, 0);

  return (
    <div
      ref={containerRef}
      onScroll={handleScroll}
      className="reasoning-panel"
      style={{ height: "400px", overflowY: "auto", border: "1px solid #ccc", padding: "8px" }}
    >
      {frames.map((frame: ReasoningFrame) => (
        <div key={frame.id} className="reasoning-frame" style={{ marginBottom: "12px", padding: "8px", borderBottom: "1px dashed #ddd" }}>
          <div className="frame-header" style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <strong>{frame.title}</strong>
            <span className="token-count" style={{ fontSize: "12px", color: "#666" }}>{frame.tokens} tokens</span>
          </div>
          <div className="frame-body" style={{ marginTop: "4px", whiteSpace: "pre-wrap" }}>
            {frame.body}
          </div>
          {onSeek && (
            <button onClick={() => onSeek(frame.id)} style={{ marginTop: "4px", fontSize: "12px" }}>
              Seek to here
            </button>
          )}
        </div>
      ))}
      <div className="total-tokens" style={{ textAlign: "right", marginTop: "8px", fontWeight: "bold" }}>
        Total: {totalTokens} tokens
      </div>
      {isStreaming && (
        <div className="streaming-indicator" style={{ marginTop: "8px", fontStyle: "italic", color: "#999" }}>
          Streaming...
        </div>
      )}
    </div>
  );
};

export default ReasoningPanel;

