import React, { useRef, useEffect, useState, useCallback } from 'react';

interface ReasoningFrame {
  id: string;
  title: string;
  body: string;
  tokens: number;
}

interface ReasoningPanelProps {
  frames: ReasoningFrame[];
  isStreaming: boolean;
  onSeek?: (id: string) => void;
}

const ReasoningPanel: React.FC<ReasoningPanelProps> = ({ frames, isStreaming, onSeek }) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const isUserScrolledRef = useRef<boolean>(false);
  const lastFrameCountRef = useRef<number>(0);
  const [totalTokens, setTotalTokens] = useState<number>(0);

  // Calculate total tokens whenever frames change
  useEffect(() => {
    const sum: number = frames.reduce((acc: number, frame: ReasoningFrame) => acc + frame.tokens, 0);
    setTotalTokens(sum);
  }, [frames]);

  // Handle scroll events to detect user manual scrolling
  const handleScroll = useCallback(() => {
    const container = containerRef.current;
    if (!container) return;

    const { scrollTop, scrollHeight, clientHeight } = container;
    const threshold = 50; // pixels from bottom to consider "at bottom"

    // If user scrolled up away from bottom, pause auto-scroll
    if (scrollHeight - scrollTop - clientHeight > threshold) {
      isUserScrolledRef.current = true;
    } else {
      // If user scrolled back to bottom, resume auto-scroll
      isUserScrolledRef.current = false;
    }
  }, []);

  // Auto-scroll to bottom when new frames are added, unless user has manually scrolled up
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // Only auto-scroll if not manually scrolled and streaming is active
    if (!isUserScrolledRef.current && isStreaming) {
      container.scrollTop = container.scrollHeight;
    }

    lastFrameCountRef.current = frames.length;
  }, [frames.length, isStreaming]);

  // Reset user scroll state when streaming ends
  useEffect(() => {
    if (!isStreaming) {
      isUserScrolledRef.current = false;
    }
  }, [isStreaming]);

  const handleFrameClick = useCallback((id: string) => {
    if (onSeek) {
      onSeek(id);
    }
  }, [onSeek]);

  return (
    <div
      ref={containerRef}
      onScroll={handleScroll}
      style={{
        height: '400px',
        overflowY: 'auto',
        border: '1px solid #ccc',
        padding: '16px',
        fontFamily: 'monospace',
        fontSize: '14px',
      }}
    >
      <div style={{ marginBottom: '12px', fontWeight: 'bold' }}>
        Total Tokens: {totalTokens}
      </div>
      {frames.map((frame: ReasoningFrame) => (
        <div
          key={frame.id}
          onClick={() => handleFrameClick(frame.id)}
          style={{
            marginBottom: '16px',
            padding: '12px',
            backgroundColor: '#f5f5f5',
            borderRadius: '4px',
            cursor: onSeek ? 'pointer' : 'default',
          }}
        >
          <div style={{ fontWeight: 'bold', marginBottom: '4px' }}>
            {frame.title}
          </div>
          <div style={{ marginBottom: '4px' }}>
            Tokens: {frame.tokens}
          </div>
          <div style={{ whiteSpace: 'pre-wrap' }}>
            {frame.body}
          </div>
        </div>
      ))}
    </div>
  );
};

export default ReasoningPanel;
