    if (!el) return;
    const { scrollTop, scrollHeight, clientHeight } = el;
    const threshold = 50;
    const isAtBottom = scrollHeight - scrollTop - clientHeight <= threshold;
    userScrolledRef.current = !isAtBottom;
  };

  useEffect(() => {
    if (frames.length > prevFramesLengthRef.current && !userScrolledRef.current) {
      const el = containerRef.current;
      if (el) {
        el.scrollTo({
          top: el.scrollHeight,
          behavior: 'smooth',
        });
      }
    }
    prevFramesLengthRef.current = frames.length;
  }, [frames.length]);

  const totalTokens: number = frames.reduce((sum: number, frame: ReasoningFrame) => sum + frame.tokens, 0);

  return (
