import React, { useRef, useEffect, useState } from 'react';

interface ReasoningFrame {
  id: string;
  title: string;
  body: string;
  tokens: number;
}

interface ReasoningPanelProps {
  frames: ReasoningFrame[];
  isStreaming: boolean;
  onSeek?: (id: string) => void;
}

const ReasoningPanel: React.FC<ReasoningPanelProps> = ({ frames, isStreaming, onSeek }) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const isUserScrolledUpRef = useRef<boolean>(false);
  const [totalTokens, setTotalTokens] = useState<number>(0);

  // 计算总 token 数
  useEffect(() => {
    const sum = frames.reduce((acc: number, frame: ReasoningFrame): number => acc + frame.tokens, 0);
    setTotalTokens(sum);
  }, [frames]);

  // 处理滚动事件，检测用户是否手动上滚
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const handleScroll = (): void => {
      const { scrollTop, scrollHeight, clientHeight } = container;
      const threshold = 50; // 距离底部 50px 内视为未上滚
      const isScrolledUp = scrollHeight - scrollTop - clientHeight > threshold;
      isUserScrolledUpRef.current = isScrolledUp;
    };

    container.addEventListener('scroll', handleScroll);
    return () => {
      container.removeEventListener('scroll', handleScroll);
    };
  }, []);

  // 依赖 frames.length 触发自动滚动（仅当未被用户上滚时）
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    if (!isUserScrolledUpRef.current) {
      container.scrollTo({
        top: container.scrollHeight,
        behavior: 'smooth',
      });
    }
  }, [frames.length]);

  // 流式结束时重置上滚状态
  useEffect(() => {
    if (!isStreaming) {
      isUserScrolledUpRef.current = false;
    }
  }, [isStreaming]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      <div
        ref={containerRef}
        style={{
          flex: 1,
          overflowY: 'auto',
          padding: '12px',
          border: '1px solid #ddd',
          borderRadius: '4px',
          backgroundColor: '#fafafa',
        }}
      >
        {frames.map((frame: ReasoningFrame): JSX.Element => (
          <div
            key={frame.id}
            onClick={() => {
              if (onSeek) {
                onSeek(frame.id);
              }
            }}
            style={{
              padding: '8px 12px',
              marginBottom: '8px',
              borderRadius: '4px',
              backgroundColor: '#fff',
              border: '1px solid #e0e0e0',
              cursor: onSeek ? 'pointer' : 'default',
            }}
          >
            <div style={{ fontWeight: 'bold', marginBottom: '4px' }}>
              {frame.title}
              <span style={{ float: 'right', fontSize: '12px', color: '#888' }}>
                {frame.tokens} tokens
              </span>
            </div>
            <div style={{ whiteSpace: 'pre-wrap', fontSize: '14px' }}>{frame.body}</div>
          </div>
        ))}
        {isStreaming && frames.length > 0 && (
          <div style={{ textAlign: 'center', color: '#888', padding: '8px' }}>
            正在生成...
          </div>
        )}
      </div>
      <div
        style={{
          padding: '8px 12px',
          borderTop: '1px solid #ddd',
          backgroundColor: '#fff',
          fontSize: '14px',
          color: '#333',
        }}
      >
        总 Token 数: {totalTokens}
      </div>
    </div>
  );
};

export default ReasoningPanel;

