  frames: ReasoningFrame[];
  isStreaming: boolean;
  onSeek?: (id: string) => void;
};

const ReasoningPanel: React.FC<ReasoningPanelProps> = ({
  frames,
  isStreaming,
  onSeek,
}): React.ReactElement => {
