  const autoScrollEnabledRef = useRef<boolean>(true);
  const [isManualScroll, setIsManualScroll] = useState<boolean>(false);

  const totalTokens = frames.reduce<number>((acc, frame) => acc + frame.tokens, 0);

  useEffect(() => {
    if (autoScrollEnabledRef.current && containerRef.current) {
      const el = containerRef.current;
      el.scrollTop = el.scrollHeight;
    }
  }, [frames.length]);

  const handleScroll = (): void => {
    if (containerRef.current) {
      const el = containerRef.current;
      const threshold = 50;
      const isAtBottom = el.scrollTop + el.clientHeight >= el.scrollHeight - threshold;
      const wasAtBottom = autoScrollEnabledRef.current;

      if (isAtBottom && !wasAtBottom) {
        autoScrollEnabledRef.current = true;
        setIsManualScroll(false);
      } else if (!isAtBottom && wasAtBottom) {
        autoScrollEnabledRef.current = false;
        setIsManualScroll(true);
      }
    }
  };

  const resumeAutoScroll = (): void => {
    autoScrollEnabledRef.current = true;
    setIsManualScroll(false);
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
