  frames: ReasoningFrame[];
  isStreaming: boolean;
  onSeek?: (id: string) => void;
}

const ReasoningPanel: React.FC<ReasoningPanelProps> = ({ frames, isStreaming, onSeek }) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const userScrolledRef = useRef<boolean>(false);
  const lastFrameCountRef = useRef<number>(0);
  const [totalTokens, setTotalTokens] = useState<number>(0);

  // Calculate total tokens whenever frames change
  useEffect(() => {
    const total = frames.reduce((sum: number, frame: ReasoningFrame) => sum + frame.tokens, 0);
    setTotalTokens(total);
  }, [frames]);

  // Handle scroll events to detect user manual scrolling
  const handleScroll = useCallback(() => {
    const container = containerRef.current;
    if (!container) return;

    const { scrollTop, scrollHeight, clientHeight } = container;
    const threshold = 50; // pixels from bottom to consider "at bottom"
    const isAtBottom = scrollHeight - scrollTop - clientHeight < threshold;

    if (!isAtBottom) {
      userScrolledRef.current = true;
    } else {
      userScrolledRef.current = false;
    }
  }, []);

  // Auto-scroll when new frames are added, unless user has manually scrolled up
  useEffect(() => {
    const currentFrameCount = frames.length;

    // Only trigger scroll if frames were added (not just re-rendered)
    if (currentFrameCount > lastFrameCountRef.current) {
      if (!userScrolledRef.current) {
        const container = containerRef.current;
        if (container) {
          container.scrollTop = container.scrollHeight;
        }
      }
    }

    lastFrameCountRef.current = currentFrameCount;
  }, [frames.length]);

  // Reset auto-scroll state when streaming ends
  useEffect(() => {
    if (!isStreaming) {
      userScrolledRef.current = false;
    }
  }, [isStreaming]);

  const handleFrameClick = useCallback((id: string) => {
    if (onSeek) {
      onSeek(id);
    }
  }, [onSeek]);

