import React, { useEffect, useRef, useState } from 'react';

interface ReasoningFrame {
  id: string;
  title: string;
  body: string;
  tokens: number;
}

interface ReasoningPanelProps {
  frames: ReasoningFrame[];
  isStreaming: boolean;
  onSeek?: (id: string) => void;
}

export const ReasoningPanel: React.FC<ReasoningPanelProps> = ({
  frames,
  isStreaming,
  onSeek,
}) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const userScrolledRef = useRef<boolean>(false);

  // 当用户手动滚动时，检测是否已手动上滚（即用户离开了底部）
  const handleScroll = () => {
    const container = containerRef.current;
    if (!container) return;

    const threshold = 50; // 距离底部50px内认为是在底部
    const distanceFromBottom = container.scrollHeight - container.scrollTop - container.clientHeight;

    if (distanceFromBottom > threshold) {
      userScrolledRef.current = true;
    } else {
      // 如果用户滚回底部，恢复自动滚动
      userScrolledRef.current = false;
    }
  };

  // 当 frames 长度变化且处于流式生成中时，尝试自动滚动到底部
  useEffect(() => {
    if (!isStreaming || userScrolledRef.current) return;

    const container = containerRef.current;
    if (!container) return;

    // 滚动到底部
    requestAnimationFrame(() => {
      container.scrollTo({
        top: container.scrollHeight,
        behavior: 'smooth',
      });
    });
  }, [frames.length, isStreaming]);

  const totalTokens: number = frames.reduce((sum: number, frame: ReasoningFrame) => sum + frame.tokens, 0);

  const handleClickFrame = (id: string) => {
    onSeek?.(id);
  };

  return (
    <div className="reasoning-panel">
