import React, { useEffect, useRef, useState, useCallback } from 'react';

export interface ReasoningFrame {
  id: string;
  title: string;
  body: string;
  tokens: number;
}

export interface ReasoningPanelProps {
  frames: ReasoningFrame[];
  isStreaming: boolean;
  onSeek?: (id: string) => void;
}

export const ReasoningPanel: React.FC<ReasoningPanelProps> = ({
  frames,
  isStreaming,
  onSeek,
}): React.ReactElement => {
  const scrollContainerRef = useRef<HTMLDivElement | null>(null);
  const isUserScrolled = useRef<boolean>(false);
  const totalTokens = frames.reduce((acc: number, frame: ReasoningFrame): number => acc + frame.tokens, 0);

  const handleScroll = useCallback((): void => {
    const container = scrollContainerRef.current;
    if (!container) return;

    // Check if user scrolled away from bottom
    const distanceFromBottom = container.scrollHeight - container.scrollTop - container.clientHeight;
    if (distanceFromBottom > 50) {
      isUserScrolled.current = true;
    } else {
      isUserScrolled.current = false;
    }
  }, []);

  const scrollToBottom = useCallback((): void => {
    const container = scrollContainerRef.current;
    if (!container) return;
    container.scrollTop = container.scrollHeight;
  }, []);

  useEffect((): void => {
    if (isStreaming && !isUserScrolled.current) {
      scrollToBottom();
    }
  }, [frames.length, isStreaming, scrollToBottom]);

  const handleSeekClick = useCallback((id: string): void => {
    if (onSeek) {
      onSeek(id);
    }
  }, [onSeek]);

  const renderFrame = (frame: ReasoningFrame): React.ReactElement => {
    return (
      <div
        key={frame.id}
        style={{
          marginBottom: '12px',
          padding: '8px',
          border: '1px solid #ddd',
          borderRadius: '4px',
        }}
      >
        <div style={{ fontWeight: 'bold', marginBottom: '4px' }}>
          {frame.title}
          <span style={{ marginLeft: '8px', fontSize: '0.85em', color: '#666' }}>
            ({frame.tokens} tokens)
          </span>
        </div>
        <div style={{ whiteSpace: 'pre-wrap', wordBreak: 'break-word' }}>{frame.body}</div>
        {onSeek && (
          <button
            onClick={(): void => handleSeekClick(frame.id)}
            style={{
              marginTop: '8px',
              padding: '2px 6px',
              fontSize: '0.8em',
              cursor: 'pointer',
            }}
          >
            Seek
          </button>
        )}
      </div>
    );
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      <div
        ref={scrollContainerRef}
        onScroll={handleScroll}
        style={{
          flex: 1,
          overflowY: 'auto',
          padding: '8px',
          border: '1px solid #ccc',
          borderRadius: '4px',
          minHeight: '200px',
        }}
      >
        {frames.map(renderFrame)}
      </div>
      <div
        style={{
          padding: '4px 8px',
          fontSize: '0.85em',
          color: '#444',
          borderTop: '1px solid #eee',
        }}
      >
        Total tokens: {totalTokens}
      </div>
    </div>
  );
};

